import { app, BrowserWindow, Menu, dialog, ipcMain, protocol, session } from "electron";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const { readUtf8, newFile } = require("./files.cjs");
const { openWorkspace } = require("./state.cjs");
const { verifiedResources, responseFor, isOwnURL } = require("./protocol.cjs");
const root = dirname(fileURLToPath(import.meta.url));
const resources = app.isPackaged
  ? join(process.resourcesPath, "catalog")
  : resolve(process.env.PORTAL_NATIVE_RESOURCES ?? join(root, "../.runtime/native-resources"));
const flag = process.argv.indexOf("--profile");
const profilePath =
  flag < 0
    ? join(
        process.env.LOCALAPPDATA ?? app.getPath("appData"),
        "JasonStysPortfolio",
        "versioned-product-knowledge-portal",
        "workspace",
      )
    : process.argv[flag + 1];
let workspace,
  window,
  startup,
  closing,
  asking,
  exiting = false,
  rendered = false,
  released = false;
const pending = new Set();
app.setName("Versioned Product Knowledge Portal");
app.commandLine.appendSwitch("disable-background-networking");
protocol.registerSchemesAsPrivileged([
  { scheme: "portal", privileges: { standard: true, secure: true, supportFetchAPI: true } },
]);

function sender(event, allowClosing = false) {
  if (
    !window ||
    event.sender !== window.webContents ||
    event.senderFrame !== window.webContents.mainFrame ||
    (!allowClosing && closing) ||
    !isOwnURL(event.senderFrame.url) ||
    new URL(event.senderFrame.url).pathname !== "/workbench/"
  )
    throw new Error("The active catalog workspace main frame is required.");
}
function accepted(operation) {
  if (closing || pending.size >= 4)
    return Promise.reject(new Error("The workspace is busy or closing."));
  const promise = Promise.resolve().then(operation);
  pending.add(promise);
  promise.then(
    () => pending.delete(promise),
    () => pending.delete(promise),
  );
  return promise;
}
async function closeOwned() {
  if (!closing)
    closing = (async () => {
      if (window && !window.isDestroyed()) {
        window.setTitle("Catalog workspace — finishing accepted local work");
        window.webContents.send("portal:closing");
      }
      await startup;
      await Promise.allSettled([...pending]);
      session.defaultSession.flushStorageData();
      exiting = true;
      app.quit();
    })().catch(() => {
      process.exitCode = 1;
      dialog.showErrorBox(
        "Catalog workspace needs review",
        "Ownership or final file work did not complete normally. The workspace was preserved; no reset or forced success was attempted.",
      );
    });
  return closing;
}
function requestQuit() {
  if (closing || asking) return;
  if (rendered && window && !window.isDestroyed()) window.webContents.send("portal:request-quit");
  else void closeOwned();
}
app.on("before-quit", (event) => {
  if (!exiting) {
    event.preventDefault();
    requestQuit();
  }
});
app.on("will-quit", (event) => {
  if (workspace && !released) {
    event.preventDefault();
    void workspace
      .close()
      .then(() => {
        released = true;
        // Exit the native will-quit callback's turn before requesting the now-authorized final quit.
        // A microtask reentrant quit can be ignored while Electron is still unwinding its prevented event.
        setImmediate(() => app.quit());
      })
      .catch(() => {
        process.exitCode = 1;
        dialog.showErrorBox(
          "Workspace lock retained",
          "Final ownership did not match. Preserve the stopped workspace for review; no lock was adopted or reset.",
        );
      });
  }
});
app.on("window-all-closed", () => {
  if (!exiting) void closeOwned();
});

function escape(value) {
  return String(value).replace(
    /[&<>"']/gu,
    (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char],
  );
}
/** Escape every author-supplied field while keeping the exported document inactive. */
function htmlCatalog(catalog) {
  const paragraphs = (values) => values.map((value) => `<p>${escape(value)}</p>`).join("");
  const sectionHtml = (section) =>
    [
      "<section>",
      `<h3>${escape(section.title)}</h3>`,
      paragraphs(section.paragraphs),
      section.steps
        ? `<ol>${section.steps.map((step) => `<li>${escape(step)}</li>`).join("")}</ol>`
        : "",
      section.warning
        ? [
            "<aside>",
            `<strong>${escape(section.warning.level)}</strong>`,
            paragraphs([
              `Condition: ${section.warning.condition}`,
              `Consequence: ${section.warning.consequence}`,
              `Avoidance: ${section.warning.avoidance}`,
            ]),
            "</aside>",
          ].join("")
        : "",
      section.code ? `<pre>${escape(section.code)}</pre>` : "",
      "</section>",
    ].join("\n");
  const topics = catalog.topics
    .map((topic) =>
      [
        "<article>",
        `<h2>${escape(topic.title)}</h2>`,
        paragraphs([`${topic.productName} ${topic.version} · ${topic.lifecycle}`, topic.summary]),
        ...topic.sections.map(sectionHtml),
        paragraphs([
          `Source assertion: ${topic.provenance.sourceId}; pages ${topic.provenance.pages.join(", ")}; SHA256 ${topic.provenance.checksum}`,
        ]),
        "</article>",
      ].join("\n"),
    )
    .join("\n");
  return [
    '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width">',
    "<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'\">",
    "<title>Saved knowledge catalog</title>",
    "<style>body{font:16px/1.6 system-ui;max-width:70rem;margin:auto;padding:2rem;color:#172235}article{border-top:2px solid #ccd5e1;margin-top:2rem}pre{white-space:pre-wrap;overflow-wrap:anywhere}aside{border:2px solid #92400e;padding:1rem}p{overflow-wrap:anywhere}</style>",
    "</head><body><h1>Saved knowledge catalog</h1>",
    "<p>Exported by Versioned Product Knowledge Portal, created by Jason Stys. Supplied provenance is an assertion; local content is not equipment guidance or authentication.</p>",
    topics,
    "</body></html>",
  ].join("\n");
}

try {
  const verified = verifiedResources(resources, root);
  const core = require(join(resources, "core/lib/workspace.js"));
  const starter = core.validateCatalog(
    core.parseCatalogJson(readUtf8(join(resources, "core/starter.json"), core.MAX_CATALOG_BYTES)),
  );
  workspace = openWorkspace(
    profilePath,
    [dirname(process.execPath), process.resourcesPath, app.getAppPath()],
    core,
    starter,
  );
  app.setPath("userData", workspace.browser);
  if (!app.requestSingleInstanceLock())
    throw new Error("This workspace already has an application owner.");
  startup = app.whenReady().then(async () => {
    protocol.handle("portal", (request) => responseFor(request, verified.assets));
    session.defaultSession.setPermissionRequestHandler((_web, _permission, callback) =>
      callback(false),
    );
    session.defaultSession.webRequest.onBeforeRequest((details, callback) =>
      callback({ cancel: !isOwnURL(details.url) && details.url !== "about:blank" }),
    );
    session.defaultSession.on("will-download", (event) => event.preventDefault());
    window = new BrowserWindow({
      width: 1440,
      height: 1000,
      minWidth: 640,
      minHeight: 600,
      show: false,
      title: "Knowledge Portal | Jason Stys | 0.2.0",
      webPreferences: {
        preload: join(root, "preload.cjs"),
        sandbox: true,
        contextIsolation: true,
        nodeIntegration: false,
        webSecurity: true,
        allowRunningInsecureContent: false,
        devTools: false,
      },
    });
    window.webContents.setWindowOpenHandler(() => ({ action: "deny" }));
    // Renderer links select native workspace panels; an attempted top-level navigation cannot discard a draft.
    // Initial loadURL is authored main-process navigation, not a will-navigate event.
    window.webContents.on("will-navigate", (event) => event.preventDefault());
    window.on("close", (event) => {
      if (!exiting) {
        event.preventDefault();
        requestQuit();
      }
    });
    ipcMain.handle("portal:load", (event) => {
      sender(event, true);
      return {
        snapshot: workspace.snapshot(),
        identity: {
          version: verified.metadata.version,
          source: verified.metadata.source,
          sourceDirty: verified.metadata.sourceDirty,
        },
        notices: readUtf8(join(resources, "core/NOTICES.txt"), 4 * 1024 * 1024),
      };
    });
    ipcMain.handle("portal:save", (event, base, catalog, imported) => {
      sender(event);
      if (
        typeof imported !== "boolean" ||
        typeof base !== "string" ||
        !/^[a-f0-9]{64}$/u.test(base)
      )
        throw new Error("Invalid save identity.");
      const admitted = core.validateCatalog(catalog);
      return accepted(() =>
        workspace.save(base, admitted, imported ? "Imported catalog" : "Saved changes"),
      );
    });
    ipcMain.handle("portal:restore", (event, base, revision) => {
      sender(event);
      if (
        typeof base !== "string" ||
        typeof revision !== "string" ||
        !/^[a-f0-9]{64}$/u.test(base) ||
        !/^[a-f0-9]{64}$/u.test(revision)
      )
        throw new Error("Invalid revision identity.");
      return accepted(() => workspace.restore(base, revision));
    });
    ipcMain.handle("portal:import", (event) => {
      sender(event);
      return accepted(async () => {
        const choice = await dialog.showOpenDialog(window, {
          title: "Import a complete validated catalog",
          properties: ["openFile"],
          filters: [{ name: "Knowledge catalog", extensions: ["json"] }],
        });
        if (choice.canceled) return null;
        if (choice.filePaths.length !== 1) throw new Error("Choose one catalog.");
        return core.validateCatalog(
          core.parseCatalogJson(readUtf8(choice.filePaths[0], core.MAX_CATALOG_BYTES)),
        );
      });
    });
    ipcMain.handle("portal:export", (event, kind) => {
      sender(event);
      if (!["json", "html"].includes(kind)) throw new Error("Choose JSON or HTML export.");
      const catalog = workspace.snapshot().catalog;
      return accepted(async () => {
        const choice = await dialog.showSaveDialog(window, {
          title: "Export the saved catalog to a new file",
          defaultPath: `knowledge-catalog.${kind}`,
          filters: [{ name: "Saved catalog", extensions: [kind] }],
        });
        if (choice.canceled) return false;
        if (!choice.filePath) throw new Error("Choose a destination.");
        const content =
          kind === "json" ? core.canonicalCatalog(catalog) + "\n" : htmlCatalog(catalog);
        if (Buffer.byteLength(content) > 8 * 1024 * 1024)
          throw new Error("Export exceeds its byte budget.");
        newFile(choice.filePath, content);
        return true;
      });
    });
    ipcMain.handle("portal:quit", (event, dirty) => {
      sender(event, true);
      if (typeof dirty !== "boolean") throw new Error("Invalid draft state.");
      if (closing) return true;
      if (!asking)
        asking = (async () => {
          if (dirty) {
            const answer = await dialog.showMessageBox(window, {
              type: "question",
              title: "Unsaved catalog draft",
              message:
                "Exit and discard unsaved draft edits? Accepted saves and exports will finish before closing.",
              buttons: ["Keep editing", "Exit application"],
              defaultId: 0,
              cancelId: 0,
              noLink: true,
            });
            if (answer.response !== 1) return false;
          }
          void closeOwned();
          return true;
        })().finally(() => {
          asking = undefined;
        });
      return asking;
    });
    let readyResolve, readyReject;
    const ready = new Promise((resolve, reject) => {
      readyResolve = resolve;
      readyReject = reject;
    });
    const timer = setTimeout(
      () => readyReject(new Error("The actual workspace did not become ready.")),
      30000,
    );
    ipcMain.handle("portal:ready", (event, success) => {
      sender(event, true);
      if (typeof success !== "boolean") throw new Error("Invalid readiness state.");
      clearTimeout(timer);
      if (success) {
        rendered = true;
        readyResolve();
      } else readyReject(new Error("The workspace refused its catalog."));
    });
    Menu.setApplicationMenu(
      Menu.buildFromTemplate([
        { label: "Workspace", submenu: [{ label: "Exit application", click: requestQuit }] },
        {
          label: "Help",
          submenu: [
            {
              label: "Usage, scope and runtime notices",
              click: () => {
                window.webContents.send("portal:help");
              },
            },
          ],
        },
      ]),
    );
    await window.loadURL("portal://workbench/workbench/");
    await ready;
    window.show();
  });
  startup.catch(async () => {
    process.exitCode = 1;
    dialog.showErrorBox(
      "Workspace startup refused",
      "The exact resources or catalog could not be loaded. Existing workspace files were preserved.",
    );
    await workspace.close();
    exiting = true;
    app.quit();
  });
} catch {
  process.exitCode = 1;
  void app.whenReady().then(async () => {
    dialog.showErrorBox(
      "Workspace admission refused",
      "Use an ordinary, separate local workspace. Existing aliases, unknown files, stale ownership and invalid revisions are preserved for review.",
    );
    await workspace?.close();
    exiting = true;
    app.quit();
  });
}
